    The server runs in a background thread so that automated tests can issue
    requests against it while a developer optionally performs manual testing
    against the same port (e.g. via a browser or curl).
    """

    def __init__(self, port, handler_class=None, host="localhost"):
        self.host = host
        self.port = port
        self.handler_class = handler_class or self._default_handler()
        self._server = None
        self._thread = None

    @staticmethod
    def _default_handler():
        class _DefaultHandler(BaseHTTPRequestHandler):
            def do_GET(self):
                self.send_response(200)
                self.send_header("Content-Type", "text/plain")
                self.end_headers()
                self.wfile.write(b"OK")

            def log_message(self, *args):
                pass  # keep test output clean

        return _DefaultHandler

