import tempfile
import os


def check_code(candidate_code, reference_code, stdin_input="", timeout=5):
    """
    Compile and run `candidate_code`, comparing its output to `reference_code`.

    Both snippets are executed in separate, short-lived subprocesses so that a
    crash, hang, or misbehaving snippet cannot affect the host process.

    Returns a dict describing the result.

    WARNING: This executes the provided code. Only run code you trust, or run
    this inside a properly sandboxed environment (container, seccomp, no network,
    restricted filesystem, resource limits). A subprocess + timeout is NOT a
    security boundary on its own.
    """

    def _compiles(code):
        try:
            compile(code, "<submitted>", "exec")
            return True, None
        except SyntaxError as e:
            return False, f"{e.__class__.__name__}: {e}"

    def _run(code):
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".py", delete=False
        ) as f:
            f.write(code)
            path = f.name
        try:
            proc = subprocess.run(
                [sys.executable, path],
                input=stdin_input,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            return {
                "returncode": proc.returncode,
                "stdout": proc.stdout,
                "stderr": proc.stderr,
                "timed_out": False,
            }
        except subprocess.TimeoutExpired:
            return {
                "returncode": None,
                "stdout": "",
                "stderr": "execution timed out",
                "timed_out": True,
            }
        finally:
            os.unlink(path)

    ok, err = _compiles(candidate_code)
    if not ok:
        return {"valid": False, "reason": "compile_error", "detail": err}

    candidate = _run(candidate_code)
    if candidate["timed_out"]:
        return {"valid": False, "reason": "timeout", "detail": candidate}
    if candidate["returncode"] != 0:
        return {"valid": False, "reason": "runtime_error", "detail": candidate}

    reference = _run(reference_code)

    valid = candidate["stdout"] == reference["stdout"]
    return {
        "valid": valid,
        "reason": "ok" if valid else "output_mismatch",
        "candidate_output": candidate["stdout"],
        "reference_output": reference["stdout"],
    }

