def create_data_filter(db_path):
    """Create a record/playback filter backed by a shelve database.

    The returned object can `record(data)` values keyed by their data
    type and `playback(data_type)` the recorded values for a given type.
    """

    class DataFilter:
        def __init__(self, path):
            self.path = path

        def record(self, data):
            type_key = type(data).__name__
            with shelve.open(self.path, writeback=True) as db:
                bucket = db.get(type_key, [])
                bucket.append(data)
                db[type_key] = bucket

        def playback(self, data_type):
            type_key = data_type if isinstance(data_type, str) else data_type.__name__
            with shelve.open(self.path) as db:
                return list(db.get(type_key, []))

        def types(self):
            with shelve.open(self.path) as db:
                return list(db.keys())

        def clear(self, data_type=None):
            with shelve.open(self.path, writeback=True) as db:
                if data_type is None:
                    db.clear()
                else:
                    type_key = data_type if isinstance(data_type, str) else data_type.__name__
                    db.pop(type_key, None)

    return DataFilter(db_path)

